code_examples.text:
when DNS_RESPONSE {
  if { [LB::server addr] equals "10.10.10.10" } {
    log local0. "Alert: [DNS::rrname] resolved to backup server"
  }
}

when DNS_RESPONSE {
    set rrs [DNS::answer]
    foreach rr $rrs {
        DNS::ttl $rr 1234
    }
    set new_rr [DNS::rr "bigip3900-30.f5net.com. 88 IN A 1.2.3.4"]
    DNS::additional insert $new_rr
}
